(()=>{
const KEY='yhh-financial-research-v1';
const uid=()=>crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2),now=()=>new Date().toISOString();
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const moneyMetrics=new Set(['Revenue','Cost of Revenue','Gross Profit','Operating Income','Net Income','Cash and Cash Equivalents','Total Assets','Total Liabilities',"Stockholders' Equity",'Total Debt','Accounts Receivable','Inventory','Operating Cash Flow','Investing Cash Flow','Financing Cash Flow','Capital Expenditure','Free Cash Flow','R&D Expenses','Market Capitalization','Stock Buybacks','Dividends','Stock-based Compensation','Equity Financing','Debt Financing']);
const metrics={'利润表':['Revenue','Cost of Revenue','Gross Profit','Gross Margin','Operating Income','Operating Margin','Net Income','Net Profit Margin','EPS','Diluted EPS'],'资产负债表':['Cash and Cash Equivalents','Total Assets','Total Liabilities',"Stockholders' Equity",'Total Debt','Net Debt','Accounts Receivable','Inventory','Current Ratio'],'现金流量表':['Operating Cash Flow','Investing Cash Flow','Financing Cash Flow','Capital Expenditure','Free Cash Flow','R&D Expenses'],'股东与估值':['Market Capitalization','Share Price','Shares Outstanding','P/E','P/S','EV/EBITDA','Stock Buybacks','Dividends Per Share','Stock-based Compensation'],'回报率':['ROE','ROA','ROIC','Interest Coverage Ratio']};
const seedIndustries=[['semiconductor','芯片与半导体','Semiconductor'],['power-energy','电力与能源','Power & Energy'],['cloud-data','云计算与数据中心','Cloud & Data Center'],['foundation-models','基础模型','Foundation Models'],['enterprise-ai','企业 AI 软件','Enterprise AI Software'],['healthcare-ai','医疗 AI','Healthcare AI'],['industrial-ai','工业 AI','Industrial AI']].map(([id,name,en])=>({id,name,en,createdAt:now()}));
const companySeed=[['nvidia','NVIDIA','NVDA','美国',1,['semiconductor','cloud-data']],['amd','AMD','AMD','美国',1,['semiconductor']],['intel','Intel','INTC','美国',1,['semiconductor']],['tsmc','TSMC','TSM','中国台湾',1,['semiconductor']],['smic','中芯国际','688981','中国',1,['semiconductor']],['asml','ASML','ASML','荷兰',1,['semiconductor']],['ge-vernova','GE Vernova','GEV','美国',1,['power-energy']],['siemens-energy','Siemens Energy','ENR','德国',1,['power-energy']],['vertiv','Vertiv','VRT','美国',1,['power-energy','cloud-data']],['schneider','施耐德电气','SU','法国',1,['power-energy','cloud-data']],['sungrow','阳光电源','300274','中国',1,['power-energy']],['microsoft','Microsoft','MSFT','美国',1,['cloud-data','enterprise-ai']],['amazon','Amazon','AMZN','美国',1,['cloud-data']],['google','Alphabet','GOOGL','美国',1,['cloud-data','foundation-models']],['equinix','Equinix','EQIX','美国',1,['cloud-data']],['digital-realty','Digital Realty','DLR','美国',1,['cloud-data']],['openai','OpenAI','—','美国',0,['foundation-models']],['anthropic','Anthropic','—','美国',0,['foundation-models']],['deepseek','DeepSeek','—','中国',0,['foundation-models']],['zhipu','智谱 AI','—','中国',0,['foundation-models']],['minimax','MiniMax','—','中国',0,['foundation-models']],['palantir','Palantir','PLTR','美国',1,['enterprise-ai']],['servicenow','ServiceNow','NOW','美国',1,['enterprise-ai']],['salesforce','Salesforce','CRM','美国',1,['enterprise-ai']],['iflytek','科大讯飞','002230','中国',1,['enterprise-ai']],['kingsoft-office','金山办公','688111','中国',1,['enterprise-ai']],['tempus','Tempus AI','TEM','美国',1,['healthcare-ai']],['ge-healthcare','GE HealthCare','GEHC','美国',1,['healthcare-ai']],['united-imaging','联影医疗','688271','中国',1,['healthcare-ai']],['infervision','推想医疗','—','中国',0,['healthcare-ai']],['shukun','数坤科技','—','中国',0,['healthcare-ai']],['siemens','Siemens','SIE','德国',1,['industrial-ai']],['rockwell','Rockwell Automation','ROK','美国',1,['industrial-ai']],['abb','ABB','ABBN','瑞士',1,['industrial-ai']],['inovance','汇川技术','300124','中国',1,['industrial-ai']]].map(([id,name,ticker,country,pub,industryIds])=>({id,name,ticker,country,isPublic:!!pub,industryIds,founded:'',listed:pub?'上市':'非上市',sector:'',description:'',products:'',customers:'',revenueSources:'',businessModel:'',technology:'',strategy:'',risks:'',createdAt:now(),updatedAt:now()}));
const fresh=()=>({version:1,companies:companySeed,industries:seedIndustries,financials:[],journals:[],questions:[],audits:[]});let state;try{state=JSON.parse(localStorage.getItem(KEY))||fresh()}catch{state=fresh()}['companies','industries','financials','journals','questions','audits'].forEach(k=>state[k]??=[]);
const save=()=>localStorage.setItem(KEY,JSON.stringify(state)),$=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)],app=$('#app'),modal=$('#modal');let view='dashboard',profileId=null,profileTab='overview';
const titles={dashboard:'研究总览',companies:'公司档案',financials:'财务数据',analytics:'财务分析',comparison:'同行业比较',journal:'研究日志',settings:'数据管理'},company=id=>state.companies.find(x=>x.id===id),industry=id=>state.industries.find(x=>x.id===id);
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2200)}
function fmt(v){if(v===null||v===undefined||v==='')return'N/A';const n=Number(v);if(!Number.isFinite(n))return esc(v);return Math.abs(n)>=1e12?(n/1e12).toFixed(2)+'T':Math.abs(n)>=1e9?(n/1e9).toFixed(2)+'B':Math.abs(n)>=1e6?(n/1e6).toFixed(2)+'M':n.toLocaleString('en-US',{maximumFractionDigits:2})}
function metricOptions(sel=''){return Object.entries(metrics).map(([g,a])=>`<optgroup label="${g}">${a.map(x=>`<option ${x===sel?'selected':''}>${x}</option>`).join('')}</optgroup>`).join('')}
function companyOptions(sel=''){return state.companies.map(c=>`<option value="${c.id}" ${c.id===sel?'selected':''}>${esc(c.name)} · ${esc(c.ticker)}</option>`).join('')}
function setView(v){view=v;profileId=null;history.replaceState(null,'','#'+v);$$('[data-nav]').forEach(x=>x.classList.toggle('active',x.dataset.nav===v));$('#pageTitle').textContent=titles[v]||'公司档案';$('#breadcrumb').textContent=`YHH RESEARCH / ${v.toUpperCase()}`;$('.sidebar').classList.remove('open');render()}
function render(){({dashboard:renderDashboard,companies:renderCompanies,financials:renderFinancials,analytics:renderAnalytics,comparison:renderComparison,journal:renderJournal,settings:renderSettings}[view]||renderDashboard)()}
function renderDashboard(){const fs=[...state.financials].sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).slice(0,5),js=[...state.journals].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,4);app.innerHTML=`<section class="metric-grid"><article class="metric-card"><small>已研究公司</small><strong>${state.companies.length}</strong><em>${state.companies.filter(x=>x.isPublic).length} 家上市公司</em></article><article class="metric-card"><small>财务数据记录</small><strong>${state.financials.length}</strong><em>${new Set(state.financials.map(x=>x.metric)).size} 个指标</em></article><article class="metric-card"><small>研究日志</small><strong>${state.journals.length}</strong><em>持续积累研究证据</em></article><article class="metric-card"><small>待解决问题</small><strong>${state.questions.filter(x=>!x.done).length}</strong><em>保持问题驱动</em></article></section><section class="dashboard-grid"><div class="panel"><div class="section-head"><div><h2>最近新增的财务数据</h2><p>所有记录均保留期间、口径与来源</p></div><button class="ghost" data-nav="financials">查看全部</button></div>${fs.length?`<div class="table-scroll"><table class="data-table"><thead><tr><th>公司</th><th>指标</th><th>期间</th><th>数值</th><th>来源</th></tr></thead><tbody>${fs.map(r=>`<tr><td>${esc(company(r.companyId)?.name)}</td><td>${r.metric}</td><td class="mono">${esc(r.period)}</td><td class="mono">${fmt(r.value)} ${esc(r.unit)}</td><td><a href="${esc(r.sourceUrl)}" target="_blank">原始来源 ↗</a></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><div><b>还没有财务记录</b>从可靠财报录入第一条数据。</div></div>`}</div><div><div class="panel"><h3>快捷入口</h3><div class="quick-grid"><button class="quick" data-action="add-company"><b>＋ 新增公司</b><small>建立公司研究档案</small></button><button class="quick" data-action="add-financial"><b>＋ 财务数据</b><small>录入年度或季度指标</small></button><button class="quick" data-action="add-journal"><b>＋ 研究笔记</b><small>记录今日发现与问题</small></button><button class="quick" data-nav="comparison"><b>⇄ 同行比较</b><small>横向查看趋势差异</small></button></div></div><div class="panel" style="margin-top:12px"><h3>最近研究</h3>${js.length?js.map(j=>`<div class="setting-row"><div><b>${esc(j.title||j.discovery)}</b><small>${esc(j.date)} · ${esc(company(j.companyId)?.name||'通用研究')}</small></div><span class="tag">${esc(j.type)}</span></div>`).join(''):`<p class="muted" style="font-size:10px">暂无研究日志。</p>`}</div></div></section>`}
function renderCompanies(){app.innerHTML=`<div class="section-head"><div><h2>公司研究库</h2><p>先认识公司，再读懂财报。非上市公司不默认进入财务比较。</p></div><button class="primary" data-action="add-company">＋ 新增公司</button></div><div class="filters"><input class="search-input" id="companySearch" placeholder="搜索公司、代码、国家或行业…"></div><div class="company-grid" id="companyGrid"></div>`;const draw=()=>{const q=$('#companySearch').value.toLowerCase(),xs=state.companies.filter(c=>[c.name,c.ticker,c.country,...c.industryIds.map(id=>industry(id)?.name)].join(' ').toLowerCase().includes(q));$('#companyGrid').innerHTML=xs.map(c=>`<article class="company-card" data-company="${c.id}"><header><div><h3>${esc(c.name)}</h3><div class="ticker">${esc(c.ticker)}</div></div><span class="tag ${c.isPublic?'live':''}">${c.isPublic?'上市':'非上市'}</span></header><p>${esc(c.description||'尚未填写公司简介。')}</p><div>${c.industryIds.map(id=>`<span class="tag">${esc(industry(id)?.name||'')}</span>`).join('')}</div></article>`).join('')};draw();$('#companySearch').oninput=draw}
function renderProfile(id){const c=company(id);if(!c)return setView('companies');profileId=id;view='profile';$('#pageTitle').textContent=c.name;$('#breadcrumb').textContent='YHH RESEARCH / COMPANIES / PROFILE';$$('[data-nav]').forEach(x=>x.classList.toggle('active',x.dataset.nav==='companies'));const tabs=[['overview','公司概况'],['statements','财务报表'],['capital','股票与融资'],['chain','产业链'],['strategy','技术与战略'],['research','综合研究']];app.innerHTML=`<section class="profile-head"><div><p class="eyebrow">COMPANY DOSSIER / ${esc(c.country)}</p><h2>${esc(c.name)} <span class="muted mono">${esc(c.ticker)}</span></h2><div>${c.industryIds.map(id=>`<span class="tag">${esc(industry(id)?.name||'')}</span>`).join('')}</div></div><div><button class="ghost" data-action="edit-company" data-id="${c.id}">编辑档案</button> <button class="primary" data-action="add-financial" data-id="${c.id}">录入数据</button></div></section><div class="profile-tabs">${tabs.map(([k,n])=>`<button data-profile-tab="${k}" class="${profileTab===k?'active':''}">${n}</button>`).join('')}</div><section id="profileContent"></section>`;renderProfileTab(c)}
function renderProfileTab(c){const root=$('#profileContent'),rs=state.financials.filter(x=>x.companyId===c.id).sort((a,b)=>b.period.localeCompare(a.period));if(profileTab==='overview')root.innerHTML=`<div class="info-grid">${[['公司名称',c.name],['股票代码',c.ticker],['国家/地区',c.country],['成立时间',c.founded||'N/A'],['上市情况',c.listed||'N/A'],['所属行业',c.sector||'N/A'],['公司简介',c.description||'待补充'],['主要产品',c.products||'待补充'],['主要客户',c.customers||'待补充'],['收入来源',c.revenueSources||'待补充'],['商业模式',c.businessModel||'待补充']].map(([k,v])=>`<div class="info-item"><small>${k}</small><b>${esc(v)}</b></div>`).join('')}</div>`;else if(profileTab==='statements'||profileTab==='capital'){const rows=rs.filter(r=>profileTab==='capital'?metrics['股东与估值'].includes(r.metric):!metrics['股东与估值'].includes(r.metric));root.innerHTML=rows.length?`<div class="table-scroll"><table class="data-table"><thead><tr><th>指标</th><th>报告期间</th><th>频率</th><th>数值</th><th>币种</th><th>类型</th><th>来源</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.metric}</td><td class="mono">${esc(r.period)}</td><td>${r.frequency}</td><td class="mono">${fmt(r.value)} ${esc(r.unit)}</td><td>${esc(r.currency||'—')}</td><td><span class="tag">${esc(r.dataType)}</span></td><td><a href="${esc(r.sourceUrl)}" target="_blank">来源 ↗</a></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><div><b>暂无数据</b>录入后将自动在这里累积历史记录。</div></div>`}else if(profileTab==='chain')root.innerHTML=`<div class="empty"><div><b>产业链关系待记录</b>可先在公司概况中维护客户与产品；关系图属于下一阶段。</div></div>`;else if(profileTab==='strategy')root.innerHTML=`<div class="info-grid"><div class="info-item"><small>核心技术 / 技术壁垒</small><b>${esc(c.technology||'待补充')}</b></div><div class="info-item"><small>未来发展战略</small><b>${esc(c.strategy||'待补充')}</b></div><div class="info-item"><small>主要经营风险</small><b>${esc(c.risks||'待补充')}</b></div></div>`;else root.innerHTML=`<div class="empty"><div><b>建立五视角研究结论</b>在研究日志中从经营、经济学、投资者、求职者与产业视角持续记录。</div></div>`}
function renderFinancials(){const rows=[...state.financials].sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));app.innerHTML=`<div class="section-head"><div><h2>财务数据记录</h2><p>同一公司、指标与报告期间重复录入时会提示；修改保留审计记录。</p></div><button class="primary" data-action="add-financial">＋ 录入数据</button></div><div class="filters"><input id="finSearch" class="search-input" placeholder="搜索公司、指标、期间…"><select id="finFreq" class="search-input"><option value="">全部频率</option><option>年度</option><option>季度</option></select></div><div class="panel table-scroll" id="financialTable"></div>`;const draw=()=>{const q=$('#finSearch').value.toLowerCase(),freq=$('#finFreq').value,xs=rows.filter(r=>(!freq||r.frequency===freq)&&[company(r.companyId)?.name,r.metric,r.period].join(' ').toLowerCase().includes(q));$('#financialTable').innerHTML=xs.length?`<table class="data-table"><thead><tr><th>公司</th><th>指标</th><th>报告期间</th><th>数值</th><th>币种</th><th>发布日期</th><th>来源</th><th></th></tr></thead><tbody>${xs.map(r=>`<tr><td><button class="link-button" data-company="${r.companyId}">${esc(company(r.companyId)?.name)}</button></td><td>${r.metric}</td><td class="mono">${esc(r.period)}</td><td class="mono">${fmt(r.value)} ${esc(r.unit)}</td><td>${esc(r.currency||'—')}</td><td>${esc(r.publishDate||'N/A')}</td><td><a href="${esc(r.sourceUrl)}" target="_blank">来源 ↗</a></td><td><button class="link-button" data-action="edit-financial" data-id="${r.id}">编辑</button></td></tr>`).join('')}</tbody></table>`:`<div class="empty"><div><b>没有匹配记录</b>缺失数据始终显示为 N/A，不会填充为 0。</div></div>`};draw();$('#finSearch').oninput=draw;$('#finFreq').onchange=draw}
function renderAnalytics(){app.innerHTML=`<div class="section-head"><div><h2>财务分析</h2><p>查看单家公司历史趋势；图表直接读取已录入记录。</p></div></div><div class="filters"><div class="field"><label>公司</label><select id="anCompany">${companyOptions(state.companies[0]?.id)}</select></div><div class="field"><label>指标</label><select id="anMetric">${metricOptions('Revenue')}</select></div><div class="field"><label>频率</label><select id="anFrequency"><option>年度</option><option>季度</option></select></div><div class="field"><label>显示</label><select id="anMode"><option value="absolute">绝对值</option><option value="growth">同比增长率</option><option value="index">标准化指数</option></select></div></div><div class="chart-card" id="analyticsChart"></div>`;['anCompany','anMetric','anFrequency','anMode'].forEach(id=>$('#'+id).onchange=()=>drawChart($('#analyticsChart'),[$('#anCompany').value],$('#anMetric').value,$('#anFrequency').value,$('#anMode').value));drawChart($('#analyticsChart'),[$('#anCompany').value],'Revenue','年度','absolute')}
let compare={industryId:'semiconductor',companies:[],metric:'Revenue',frequency:'年度',mode:'index'};
function renderComparison(){const ind=industry(compare.industryId)||state.industries[0];compare.industryId=ind?.id||'';const eligible=state.companies.filter(c=>c.industryIds.includes(compare.industryId));if(!compare.companies.length)compare.companies=eligible.filter(c=>state.financials.some(r=>r.companyId===c.id)).map(c=>c.id);app.innerHTML=`<div class="section-head"><div><p class="eyebrow">CORE EXPERIENCE</p><h2>同行业比较</h2><p>选择行业后自动加载公司；默认选中已有财务数据的公司。</p></div><button class="ghost" data-nav="settings">编辑行业与名单</button></div><div class="industry-picker">${state.industries.map(x=>`<button class="industry-pill ${x.id===compare.industryId?'active':''}" data-industry="${x.id}">${esc(x.name)}<br><span class="muted">${esc(x.en)}</span></button>`).join('')}</div><div class="compare-layout" style="margin-top:12px"><aside class="control-panel"><div class="control-group"><h3>01 / 公司</h3><div id="compareCompanies">${eligible.map(c=>`<label class="company-check ${compare.companies.includes(c.id)?'active':''}"><input type="checkbox" value="${c.id}" ${compare.companies.includes(c.id)?'checked':''}>${esc(c.name)} ${state.financials.some(r=>r.companyId===c.id)?'':'· N/A'}</label>`).join('')||'<span class="muted">该行业暂无公司</span>'}</div></div><div class="control-group"><h3>02 / 指标</h3><select id="compareMetric" class="search-input">${metricOptions(compare.metric)}</select></div><div class="control-group"><h3>03 / 时间频率</h3><div class="segmented"><button data-frequency="年度" class="${compare.frequency==='年度'?'active':''}">年度</button><button data-frequency="季度" class="${compare.frequency==='季度'?'active':''}">季度</button></div></div><div class="control-group"><h3>04 / 比较方式</h3><div class="segmented"><button data-mode="absolute" class="${compare.mode==='absolute'?'active':''}">绝对值</button><button data-mode="growth" class="${compare.mode==='growth'?'active':''}">同比</button><button data-mode="index" class="${compare.mode==='index'?'active':''}">基期=100</button></div></div></aside><div><div class="chart-card" id="compareChart"></div><div class="panel table-scroll" style="margin-top:12px"><h3>公司概览 · 最近年度</h3><div id="overviewTable"></div></div></div></div>`;drawComparison();$('#compareMetric').onchange=e=>{compare.metric=e.target.value;drawComparison()};$$('#compareCompanies input').forEach(x=>x.onchange=()=>{compare.companies=$$('#compareCompanies input:checked').map(i=>i.value);$$('.company-check').forEach(l=>l.classList.toggle('active',l.querySelector('input').checked));drawComparison()})}
function drawComparison(){drawChart($('#compareChart'),compare.companies,compare.metric,compare.frequency,compare.mode);const latest=(cid,m)=>state.financials.filter(r=>r.companyId===cid&&r.metric===m&&r.frequency==='年度').sort((a,b)=>b.period.localeCompare(a.period))[0];$('#overviewTable').innerHTML=`<table class="data-table"><thead><tr><th>公司</th><th>最近年度收入</th><th>毛利率</th><th>净利润</th><th>EPS</th></tr></thead><tbody>${state.companies.filter(c=>c.industryIds.includes(compare.industryId)).map(c=>`<tr><td><button class="link-button" data-company="${c.id}">${esc(c.name)}</button></td>${['Revenue','Gross Margin','Net Income','EPS'].map(m=>{const r=latest(c.id,m);return`<td class="mono ${r?'':'na'}">${r?`${fmt(r.value)} ${esc(r.unit)}`:'N/A'}</td>`}).join('')}</tr>`).join('')}</tbody></table>`}
function chartSeries(ids,metric,frequency,mode){return ids.map(cid=>{let vals=state.financials.filter(r=>r.companyId===cid&&r.metric===metric&&r.frequency===frequency).sort((a,b)=>a.period.localeCompare(b.period)).map(r=>({period:r.period,value:Number(r.value),currency:r.currency,unit:r.unit})).filter(x=>Number.isFinite(x.value));if(mode==='growth')vals=vals.map((x,i)=>({...x,value:i&&vals[i-1].value!==0?(x.value/vals[i-1].value-1)*100:null})).filter(x=>x.value!==null);if(mode==='index'){const base=vals.find(x=>x.value!==0);vals=base?vals.map(x=>({...x,value:x.value/base.value*100})):[]}return{company:company(cid),values:vals}})}
function drawChart(root,ids,metric,frequency,mode){if(!root)return;const series=chartSeries(ids,metric,frequency,mode),all=series.flatMap(s=>s.values),currencies=[...new Set(all.map(x=>x.currency).filter(Boolean))],periods=[...new Set(all.map(x=>x.period))].sort(),colors=['#c8ff74','#73b8ff','#ff9b72','#d58cff','#4bd89c','#f3c969'];if(!all.length){root.innerHTML=`<div class="chart-head"><div><p class="eyebrow">DYNAMIC DATABASE CHART</p><h3>${esc(metric)} · ${esc(frequency)}</h3><p>${mode==='index'?'标准化指数（首个非零报告期=100）':mode==='growth'?'同比增长率':'绝对值'}</p></div></div><div class="empty"><div><b>暂无可绘制数据</b>请先录入同一指标与频率的数据。缺失值不会被填充为 0。</div></div>`;return}const W=900,H=270,pad={l:58,r:20,t:20,b:35},vals=all.map(x=>x.value),min=Math.min(...vals),max=Math.max(...vals),lo=min===max?min-1:min,hi=min===max?max+1:max,range=hi-lo||1,x=p=>pad.l+(periods.indexOf(p)/Math.max(1,periods.length-1))*(W-pad.l-pad.r),y=v=>pad.t+(hi-v)/range*(H-pad.t-pad.b);const lines=[0,.25,.5,.75,1].map(q=>{const yy=pad.t+q*(H-pad.t-pad.b),val=hi-q*range;return`<line x1="${pad.l}" y1="${yy}" x2="${W-pad.r}" y2="${yy}" class="grid-line"/><text x="${pad.l-8}" y="${yy+3}" text-anchor="end" class="axis-label">${fmt(val)}</text>`}).join(''),paths=series.map((s,i)=>`<polyline points="${s.values.map(v=>`${x(v.period)},${y(v.value)}`).join(' ')}" fill="none" stroke="${colors[i%colors.length]}" stroke-width="2" vector-effect="non-scaling-stroke"/>${s.values.map(v=>`<circle cx="${x(v.period)}" cy="${y(v.value)}" r="3" fill="${colors[i%colors.length]}"><title>${esc(s.company?.name)} · ${esc(v.period)} · ${fmt(v.value)}</title></circle>`).join('')}`).join('');root.innerHTML=`<div class="chart-head"><div><p class="eyebrow">DYNAMIC DATABASE CHART</p><h3>${esc(metric)} · ${esc(frequency)}</h3><p>${mode==='index'?'标准化指数（首个非零报告期=100）':mode==='growth'?'同比增长率':'绝对值'}</p></div><span class="tag">${periods.length} 个报告期</span></div>${currencies.length>1&&moneyMetrics.has(metric)?`<div class="warning">检测到多币种（${currencies.join(' / ')}）。绝对值不可直接比较；建议切换“基期=100”，并核对会计口径。</div>`:''}<div class="chart-wrap"><svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none">${lines}${periods.map(p=>`<text x="${x(p)}" y="${H-8}" text-anchor="middle" class="axis-label">${esc(p)}</text>`).join('')}${paths}</svg></div><div class="legend">${series.map((s,i)=>`<span><i style="background:${colors[i%colors.length]}"></i>${esc(s.company?.name||'')}</span>`).join('')}</div>`}
function renderJournal(){app.innerHTML=`<div class="section-head"><div><h2>每日研究日志</h2><p>把发现、数据、思考、问题与来源连接到公司档案。</p></div><button class="primary" data-action="add-journal">＋ 新增日志</button></div><div class="filters"><input id="journalSearch" class="search-input" placeholder="搜索内容或标签…"><select id="journalCompany" class="search-input"><option value="">全部公司</option>${companyOptions()}</select></div><div id="journalList"></div>`;const draw=()=>{const q=$('#journalSearch').value.toLowerCase(),cid=$('#journalCompany').value,xs=[...state.journals].sort((a,b)=>b.date.localeCompare(a.date)).filter(j=>(!cid||j.companyId===cid)&&Object.values(j).join(' ').toLowerCase().includes(q));$('#journalList').innerHTML=xs.length?xs.map(j=>`<article class="journal-card"><header><div><span class="tag">${esc(j.type)}</span><h3>${esc(j.title||j.discovery)}</h3></div><span class="mono muted">${esc(j.date)}</span></header><p>${esc(j.discovery)}</p>${j.thoughts?`<p><b>个人思考：</b>${esc(j.thoughts)}</p>`:''}<footer><span>${j.companyId?`<button class="link-button" data-company="${j.companyId}">${esc(company(j.companyId)?.name)}</button>`:'通用研究'} ${esc(j.tags||'')}</span><span><button class="link-button" data-action="edit-journal" data-id="${j.id}">编辑</button> · <button class="link-button negative" data-action="delete-journal" data-id="${j.id}">删除</button></span></footer></article>`).join(''):`<div class="empty"><div><b>还没有研究日志</b>记录今天发现的一件事。</div></div>`};draw();$('#journalSearch').oninput=draw;$('#journalCompany').onchange=draw}
function renderSettings(){app.innerHTML=`<div class="section-head"><div><h2>数据与分类管理</h2><p>行业与公司名单可随研究变化扩展，无需修改代码。</p></div></div><div class="settings-grid"><section class="panel"><div class="section-head"><div><h2>行业分类</h2><p>${state.industries.length} 个分类</p></div><button class="ghost" data-action="add-industry">＋ 新增</button></div>${state.industries.map(i=>`<div class="setting-row"><div><b>${esc(i.name)}</b><small>${esc(i.en)} · ${state.companies.filter(c=>c.industryIds.includes(i.id)).length} 家公司</small></div><button class="link-button" data-action="edit-industry" data-id="${i.id}">编辑</button></div>`).join('')}</section><section class="panel"><h3>备份与迁移</h3><p class="muted" style="font-size:10px;line-height:1.7">当前版本使用浏览器本地数据库，适合个人使用。定期导出 JSON 备份，可在另一设备导入。</p><div class="quick-grid"><button class="quick" data-action="export"><b>↓ 导出完整备份</b><small>公司、行业、财务、日志与审计记录</small></button><button class="quick" data-action="import"><b>↑ 导入备份</b><small>导入前会校验文件结构</small></button></div><h3 style="margin-top:22px">审计记录</h3><p class="muted" style="font-size:10px">${state.audits.length} 条数据修改记录</p><div class="bar-mini"><i style="width:${Math.min(100,state.audits.length*4)}%"></i></div></section></div>`}
function openModal(title,eyebrow,body){$('#modalTitle').textContent=title;$('#modalEyebrow').textContent=eyebrow;$('#modalBody').innerHTML=body;modal.showModal()}
function companyForm(c={}){openModal(c.id?'编辑公司档案':'新增公司','COMPANY DOSSIER',`<form id="companyForm"><div class="form-grid"><div class="field"><label>公司名称 *</label><input name="name" required value="${esc(c.name||'')}"></div><div class="field"><label>股票代码</label><input name="ticker" value="${esc(c.ticker||'')}"></div><div class="field"><label>国家/地区</label><input name="country" value="${esc(c.country||'')}"></div><div class="field"><label>成立时间</label><input name="founded" value="${esc(c.founded||'')}"></div><div class="field"><label>上市情况</label><select name="isPublic"><option value="true" ${c.isPublic?'selected':''}>上市</option><option value="false" ${c.isPublic===false?'selected':''}>非上市</option></select></div><div class="field"><label>所属行业（可多选）</label><select name="industryIds" multiple size="4">${state.industries.map(i=>`<option value="${i.id}" ${c.industryIds?.includes(i.id)?'selected':''}>${esc(i.name)}</option>`).join('')}</select></div><div class="field wide"><label>公司简介</label><textarea name="description">${esc(c.description||'')}</textarea></div>${[['products','主要产品'],['customers','主要客户'],['revenueSources','收入来源'],['businessModel','商业模式'],['technology','核心技术 / 壁垒'],['strategy','未来发展战略'],['risks','主要经营风险']].map(([n,l])=>`<div class="field"><label>${l}</label><textarea name="${n}">${esc(c[n]||'')}</textarea></div>`).join('')}</div><div class="form-actions"><button type="button" class="ghost" data-close>取消</button><button class="primary" type="submit">保存公司</button></div></form>`);$('#companyForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),pub=f.get('isPublic')==='true',obj={...c,id:c.id||uid(),name:f.get('name'),ticker:f.get('ticker')||'—',country:f.get('country'),founded:f.get('founded'),isPublic:pub,listed:pub?'上市':'非上市',industryIds:[...e.target.elements.industryIds.selectedOptions].map(o=>o.value),description:f.get('description'),products:f.get('products'),customers:f.get('customers'),revenueSources:f.get('revenueSources'),businessModel:f.get('businessModel'),technology:f.get('technology'),strategy:f.get('strategy'),risks:f.get('risks'),createdAt:c.createdAt||now(),updatedAt:now()};if(c.id)state.companies[state.companies.findIndex(x=>x.id===c.id)]=obj;else state.companies.push(obj);save();modal.close();toast('公司档案已保存');c.id?renderProfile(c.id):render()}}
function financialForm(r={},preset=''){openModal(r.id?'编辑财务记录':'录入财务数据','VERIFIED FINANCIAL RECORD',`<form id="financialForm"><div class="form-grid"><div class="field"><label>公司 *</label><select name="companyId" required>${companyOptions(r.companyId||preset)}</select></div><div class="field"><label>指标 *</label><select name="metric">${metricOptions(r.metric||'Revenue')}</select></div><div class="field"><label>数值 *</label><input type="number" step="any" name="value" required value="${esc(r.value??'')}"></div><div class="field"><label>单位 *</label><input name="unit" required value="${esc(r.unit||'USD')}" placeholder="USD / % / per share"></div><div class="field"><label>币种</label><select name="currency"><option value="">不适用</option>${['USD','CNY','EUR','JPY','TWD','HKD','GBP'].map(x=>`<option ${r.currency===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>年度或季度 *</label><select name="frequency"><option ${r.frequency==='年度'?'selected':''}>年度</option><option ${r.frequency==='季度'?'selected':''}>季度</option></select></div><div class="field"><label>报告期间 *</label><input name="period" required value="${esc(r.period||'')}" placeholder="2025 / FY2025 Q1"></div><div class="field"><label>财年 *</label><input name="fiscalYear" required value="${esc(r.fiscalYear||'')}" placeholder="FY2025"></div><div class="field"><label>数据发布日期</label><input type="date" name="publishDate" value="${esc(r.publishDate||'')}"></div><div class="field"><label>数据类型</label><select name="dataType">${['原始数据','计算数据','估算数据'].map(x=>`<option ${r.dataType===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field wide"><label>数据来源链接 *</label><input type="url" name="sourceUrl" required value="${esc(r.sourceUrl||'')}" placeholder="https://… 官方财报或可靠来源"></div><div class="field wide"><label>口径备注</label><textarea name="notes" placeholder="会计口径、重述、财年截止日等">${esc(r.notes||'')}</textarea></div></div><div class="form-actions"><button type="button" class="ghost" data-close>取消</button><button class="primary" type="submit">保存财务记录</button></div></form>`);$('#financialForm').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target)),dup=state.financials.find(x=>x.id!==r.id&&x.companyId===f.companyId&&x.metric===f.metric&&x.period.toLowerCase()===f.period.toLowerCase());if(dup&&!confirm('同一公司、指标和报告期间已有记录。是否仍要继续保存？'))return;const obj={...r,...f,id:r.id||uid(),value:Number(f.value),createdAt:r.createdAt||now(),updatedAt:now()};if(r.id){state.audits.push({id:uid(),recordId:r.id,action:'update',before:r,after:obj,createdAt:now()});state.financials[state.financials.findIndex(x=>x.id===r.id)]=obj}else{state.financials.push(obj);state.audits.push({id:uid(),recordId:obj.id,action:'create',after:obj,createdAt:now()})}save();modal.close();toast('财务记录已保存');profileId?renderProfile(profileId):render()}}
function journalForm(j={}){openModal(j.id?'编辑研究日志':'新增研究日志','DAILY RESEARCH JOURNAL',`<form id="journalForm"><div class="form-grid"><div class="field"><label>日期 *</label><input type="date" name="date" required value="${esc(j.date||new Date().toISOString().slice(0,10))}"></div><div class="field"><label>公司</label><select name="companyId"><option value="">通用研究</option>${companyOptions(j.companyId)}</select></div><div class="field"><label>研究类型</label><select name="type">${['公司研究','财报阅读','财务数据','产业链','技术与战略','个人思考'].map(x=>`<option ${j.type===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>标题</label><input name="title" value="${esc(j.title||'')}"></div>${[['discovery','今日发现 *'],['keyData','关键财务数据'],['thoughts','个人思考'],['questions','待研究问题'],['sources','参考来源']].map(([n,l])=>`<div class="field wide"><label>${l}</label><textarea name="${n}" ${n==='discovery'?'required':''}>${esc(j[n]||'')}</textarea></div>`).join('')}<div class="field wide"><label>标签（用空格分隔）</label><input name="tags" value="${esc(j.tags||'')}"></div></div><div class="form-actions"><button type="button" class="ghost" data-close>取消</button><button class="primary" type="submit">保存日志</button></div></form>`);$('#journalForm').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target)),obj={...j,...f,id:j.id||uid(),createdAt:j.createdAt||now(),updatedAt:now()};if(j.id)state.journals[state.journals.findIndex(x=>x.id===j.id)]=obj;else state.journals.push(obj);save();modal.close();toast('研究日志已保存');render()}}
function industryForm(i={}){openModal(i.id?'编辑行业分类':'新增行业分类','EDITABLE TAXONOMY',`<form id="industryForm"><div class="form-grid"><div class="field"><label>中文名称 *</label><input name="name" required value="${esc(i.name||'')}"></div><div class="field"><label>英文名称 *</label><input name="en" required value="${esc(i.en||'')}"></div><div class="field wide"><label>包含公司</label><select name="companies" multiple size="10">${state.companies.map(c=>`<option value="${c.id}" ${c.industryIds.includes(i.id)?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div></div><div class="form-actions"><button type="button" class="ghost" data-close>取消</button><button class="primary" type="submit">保存分类</button></div></form>`);$('#industryForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),id=i.id||uid(),obj={...i,id,name:f.get('name'),en:f.get('en'),createdAt:i.createdAt||now(),updatedAt:now()},selected=[...e.target.elements.companies.selectedOptions].map(o=>o.value);state.companies.forEach(c=>{c.industryIds=c.industryIds.filter(x=>x!==id);if(selected.includes(c.id))c.industryIds.push(id)});if(i.id)state.industries[state.industries.findIndex(x=>x.id===i.id)]=obj;else state.industries.push(obj);save();modal.close();toast('行业分类已保存');render()}}
function exportData(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`yhh-financial-research-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(url);toast('备份已导出')}
document.addEventListener('click',e=>{const nav=e.target.closest('[data-nav]');if(nav){e.preventDefault();setView(nav.dataset.nav);return}const cp=e.target.closest('[data-company]');if(cp){renderProfile(cp.dataset.company);return}const tab=e.target.closest('[data-profile-tab]');if(tab){profileTab=tab.dataset.profileTab;renderProfile(profileId);return}const ind=e.target.closest('[data-industry]');if(ind){compare.industryId=ind.dataset.industry;compare.companies=[];renderComparison();return}const fr=e.target.closest('[data-frequency]');if(fr){compare.frequency=fr.dataset.frequency;$$('[data-frequency]').forEach(x=>x.classList.toggle('active',x===fr));drawComparison();return}const mo=e.target.closest('[data-mode]');if(mo){compare.mode=mo.dataset.mode;$$('[data-mode]').forEach(x=>x.classList.toggle('active',x===mo));drawComparison();return}const a=e.target.closest('[data-action]');if(a){const id=a.dataset.id;({'add-company':()=>companyForm(),'edit-company':()=>companyForm(company(id)),'add-financial':()=>financialForm({},id),'edit-financial':()=>financialForm(state.financials.find(x=>x.id===id)),'add-journal':()=>journalForm(),'edit-journal':()=>journalForm(state.journals.find(x=>x.id===id)),'delete-journal':()=>{if(confirm('确定删除这条研究日志？')){state.journals=state.journals.filter(x=>x.id!==id);save();render()}},'add-industry':()=>industryForm(),'edit-industry':()=>industryForm(industry(id)),'export':exportData,'import':()=>$('#importFile').click()}[a.dataset.action]||(()=>{}))();return}if(e.target.closest('[data-close]'))modal.close()});
$('#importFile').onchange=e=>{const file=e.target.files[0];if(!file)return;const rd=new FileReader();rd.onload=()=>{try{const x=JSON.parse(rd.result);if(!Array.isArray(x.companies)||!Array.isArray(x.industries)||!Array.isArray(x.financials))throw Error();if(confirm('导入将覆盖当前浏览器中的全部数据。继续？')){state=x;save();render();toast('备份导入成功')}}catch{alert('文件不是有效的 YHH Research 备份。')}};rd.readAsText(file)};
$('#mobileMenu').onclick=()=>$('.sidebar').classList.toggle('open');$('#globalSearchBtn').onclick=()=>{setView('companies');setTimeout(()=>$('#companySearch')?.focus(),0)};window.addEventListener('hashchange',()=>{const h=location.hash.slice(1);if(titles[h]&&h!==view)setView(h)});const initial=location.hash.slice(1);setView(titles[initial]?initial:'dashboard');
})();
